class Range {
  constructor(s, e) { this.s = s; this.e = e; }
  [Symbol.iterator]() {
    let n = this.s;
    const e = this.e;
    return { next: () => n <= e ? { value: n++, done: false } : { done: true } };
  }
}
console.log([...new Range(1, 3)]);
